// Bounded call: timeout + retries + backoff (plain JS pattern)
async function boundedCall(fn, { timeoutMs = 5000, tries = 2, backoffMs = 500 } = {}) {
  let lastError;
  for (let i = 0; i < tries; i++) {
    try {
      return { ok: true, value: await Promise.race([
        fn(),
        new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), timeoutMs)),
      ]) };
    } catch (e) { lastError = e; await new Promise((r) => setTimeout(r, backoffMs * (i + 1))); }
  }
  return { ok: false, error: String(lastError && lastError.message || lastError) };
}
// Attempts AND time bounded; backoff linear-ish; failure as data, never thrown.

// Idempotent executor: keys + recorded outcomes (plain JS)
function makeIdempotent() {
  const seen = new Map(); // key -> recorded outcome
  return async function run(key, fn) {
    if (seen.has(key)) return { ok: true, outcome: seen.get(key), replay: true };
    const outcome = await fn();
    seen.set(key, outcome);
    return { ok: true, outcome, replay: false };
  };
}
// Crash between execute and record still double-applies: production stores
// keys durably (DB unique constraint) — memory map demonstrates semantics.

