// Sync twin (same key semantics, no awaits — playground-safe)
function makeIdempotent() {
  const seen = new Map();
  return function run(key, fn) {
    if (seen.has(key)) return { ok: true, outcome: seen.get(key), replay: true };
    const outcome = fn();
    seen.set(key, outcome);
    return { ok: true, outcome, replay: false };
  };
}
let charges = 0;
const run = makeIdempotent();
function charge() { charges++; return { charged: 129 }; }
const r1 = run('op-1', charge);
const r2 = run('op-1', charge);
console.log('charges after repeat=' + charges);
console.log('r1 replay=' + r1.replay + ' r2 replay=' + r2.replay);
const r3 = run('op-2', charge);
console.log('r3 fresh=' + (!r3.replay) + ' charges=' + charges);

